const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for Punjab and Haryana
  const punjab = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'India'),
      ee.Filter.eq('ADM1_NAME', 'Punjab')
    ));

  const haryana = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'India'),
      ee.Filter.eq('ADM1_NAME', 'Haryana')
    ));

  // 2. Load VIIRS active fire data for November 8, 2024
  const fireData = ee.ImageCollection('FIRMS')
    .filterDate('2024-11-08', '2024-11-09');

  const fireSize = fireData.size().getInfo();
  console.log(`Fire collection size: ${fireSize}`);

  if (fireSize === 0) {
    console.log("No fire data available for November 8, 2024.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Get fire image
  const fireImage = fireData.mosaic();

  // 4. Count fires in Punjab
  const punjabGeom = punjab.geometry();
  const punjabStats = fireImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: punjabGeom,
    scale: 1000,
    maxPixels: 1e9
  });

  const punjabCount = punjabStats.get('T21').getInfo();

  // 5. Count fires in Haryana
  const haryanaGeom = haryana.geometry();
  const haryanaStats = fireImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: haryanaGeom,
    scale: 1000,
    maxPixels: 1e9
  });

  const haryanaCount = haryanaStats.get('T21').getInfo();

  // 6. Validation and output
  if (punjabCount === null || haryanaCount === null) {
    console.log("Calculation failed - null values returned.");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Punjab fire count: ${punjabCount}`);
  console.log(`Haryana fire count: ${haryanaCount}`);

  // 7. Final answer
  if (punjabCount > haryanaCount) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
